    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p2, v_read_unit1, 'The passage is primarily concerned with:', 'Clara''s six-hour drive from Portland.', 'Clara''s grief and her discovery of an object connected to her mother''s hidden past.', 'The deteriorating condition of the childhood home.', 'The history of the music box.', 'B', 'The central focus is Clara returning home after her mother''s death and finding a music box that unlocks unspoken grief — this is the passage''s main concern.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p2, v_read_unit1, 'As used in the second paragraph, "inflates" most nearly means:', 'diminishes', 'exaggerates', 'distorts beyond recognition', 'clarifies', 'B', '"Memory inflates everything it touches" means memory makes things seem larger than they were. "Exaggerates" best captures this meaning.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p2, v_read_unit1, 'When Clara arrives, the house strikes her as:', 'exactly as she remembered it.', 'larger and more welcoming than expected.', 'smaller and more neglected than in her memory.', 'completely unfamiliar and strange.', 'C', 'The passage states the house is "smaller than she remembered" and details the sagging porch and overgrown rosebushes.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 3),
    (v_read_id, v_read_p2, v_read_unit1, 'The cedar smell of the wooden blocks in every drawer primarily serves to:', 'explain why the music box was stored there.', 'suggest Clara has always disliked cedar.', 'evoke the mother''s careful, habitual presence in the house.', 'contrast the bureau with the rest of the neglected house.', 'C', 'The cedar blocks placed in every drawer are a sensory trace of the mother''s careful habits, evoking her enduring presence.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p2, v_read_unit1, 'Clara''s reaction to the melody — listening three times before crying — is best described as:', 'immediate and uncontrolled.', 'delayed and reluctant.', 'indifferent and detached.', 'confused and frightened.', 'B', 'Clara listens to the melody repeat three times before "finally" crying, indicating a delayed, reluctant emotional release.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p2, v_read_unit1, '"That information would change nothing and everything" most likely means:', 'Clara is uncertain whether her aunt''s information is accurate.', 'The revelation is simultaneously transformative and leaves her core grief unchanged.', 'Clara decides to ignore what she has been told.', 'The information has no emotional impact on Clara.', 'B', 'The paradox conveys that the factual revelation shifts Clara''s understanding profoundly while the grief itself remains unchanged.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 6),
    (v_read_id, v_read_p2, v_read_unit1, 'Clara''s rehearsal of apologies and recriminations during the drive most strongly suggests:', 'She had an unresolved relationship with her mother.', 'She was planning to sell the house and needed to justify the decision.', 'She was afraid of the deteriorating building.', 'She had not visited in many years due to bad roads.', 'A', 'The words Clara rehearsed — apologies and recriminations "never delivered" while her mother was alive — imply unresolved conflict between them.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p2, v_read_unit1, 'The rosebushes growing "wild and unpruned past the fence" most likely symbolize:', 'Clara''s neglect of the property since arriving.', 'The passage of time and the absence of the mother''s care.', 'The rosebushes were always difficult to maintain.', 'Clara intends to prune them before leaving.', 'B', 'The overgrown rosebushes — once tended with "obsession" — now growing wild symbolize time passed and the loss of their devoted caretaker.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 8),
    (v_read_id, v_read_p2, v_read_unit1, 'Clara''s understanding that her mother "kept something beautiful hidden" most directly conveys:', 'Anger that her mother was secretive throughout her life.', 'Relief that the secret is finally known.', 'A recognition that her mother had a complex inner life unknown to Clara.', 'Sadness that the music box is physically damaged.', 'C', 'The realization is a quiet recognition — her mother possessed an interior world, including hidden grief, that Clara never knew.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 9),
    (v_read_id, v_read_p2, v_read_unit1, 'The tone of the passage is best described as:', 'bitter and accusatory.', 'reflective and melancholic.', 'lighthearted and nostalgic.', 'urgent and suspenseful.', 'B', 'The slow pace, imagery of deterioration and hidden objects, and focus on unspoken grief create a reflective, melancholic tone throughout.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p2, v_read_unit2, 'The passage primarily discusses:', 'The 1964 murder of Kitty Genovese and its legal aftermath.', 'Why people fail to help in emergencies when others are present, and challenges to that finding.', 'The history of social psychology as a discipline.', 'How CCTV footage is used in criminal investigations.', 'B', 'The passage introduces the bystander effect through the Genovese case, explains Darley and Latané''s research, and presents a 2019 challenge to it.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p2, v_read_unit2, 'In the 1968 study, when participants believed they were the sole witness, what percentage sought help?', '31 percent', '55 percent', '85 percent', '90 percent', 'C', 'The passage states explicitly: "When participants believed they were the sole witness, 85 percent sought help within sixty seconds."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p2, v_read_unit2, 'According to the passage, "diffusion of responsibility" means:', 'People are unaware an emergency is occurring.', 'People look to others for cues and assume everything is fine.', 'Each person feels less personally obligated to act because others could share the burden.', 'People intervene more readily when a larger group is present.', 'C', 'The passage defines diffusion of responsibility as the feeling that individual obligation decreases when others are present to share it.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p2, v_read_unit2, '"Pluralistic ignorance" as described in the passage refers to:', 'A lack of knowledge about emergency procedures.', 'Each bystander looking to others for cues and concluding no emergency exists because everyone appears calm.', 'The belief that someone more qualified will intervene.', 'Confusion caused by multiple people giving conflicting instructions.', 'B', 'The passage defines pluralistic ignorance as a cycle where each person looks to others, sees apparent calm, and concludes the situation is not serious.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p2, v_read_unit2, 'What did the 2019 meta-analysis find about real-world emergencies?', 'Bystanders intervened in only 31 percent of cases.', 'Groups of five or more never intervened.', 'Bystanders intervened in at least 90 percent of the incidents reviewed.', 'CCTV footage reduced bystander intervention rates.', 'C', 'The passage states the 2019 meta-analysis found at least one bystander intervened in 90 percent of 7,500 real-world cases.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 5),
    (v_read_id, v_read_p2, v_read_unit2, 'The researchers in the 2019 study suggest lab findings differ from real emergencies because:', 'Laboratory participants were less educated than real-world bystanders.', 'Real emergencies involve visible distress and proximity that activate helping behavior lab settings suppress.', 'The Genovese case was misreported and never actually happened.', 'CCTV cameras change how people behave.', 'B', 'The researchers argue that real-world cues — eye contact, visible distress, physical proximity — override the diffusion laboratory studies measured.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 6),
    (v_read_id, v_read_p2, v_read_unit2, 'When participants believed five others were also listening, their response was:', 'More likely to intervene, with faster response times.', 'Unchanged compared to sole-witness participants.', 'Less likely to intervene, with significantly longer response times.', 'More likely to call police rather than intervene directly.', 'C', 'The passage states only 31 percent intervened (vs. 85%) and "their response times were significantly longer."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 7),
    (v_read_id, v_read_p2, v_read_unit2, 'The passage notes that newspaper reports about the Genovese case were "later found to be exaggerated." This detail most likely serves to:', 'Undermine the legitimacy of Darley and Latané''s research.', 'Acknowledge that the original incident was less severe than reported.', 'Show that the case''s factual accuracy mattered less than the psychological questions it raised.', 'Argue that the 1964 bystanders acted correctly.', 'C', 'By noting the exaggeration but continuing to discuss the research it prompted, the author implies the psychological questions are valid regardless of the case''s exact facts.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 8),
    (v_read_id, v_read_p2, v_read_unit2, 'The main purpose of the final paragraph is to:', 'Prove that the bystander effect does not exist.', 'Describe how CCTV technology has improved emergency response.', 'Present evidence that complicates or qualifies the original bystander effect findings.', 'Argue that Darley and Latané''s 1968 methodology was flawed.', 'C', 'The final paragraph introduces a 2019 study whose findings challenge the universality of the bystander effect, complicating rather than disproving the original research.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p2, v_read_unit2, 'The author''s treatment of Darley and Latané''s research is best described as:', 'Dismissive, suggesting the research was poorly designed.', 'Uncritical, accepting all findings without qualification.', 'Balanced, presenting the findings and then evidence that complicates them.', 'Partisan, clearly favoring the 2019 meta-analysis over the original study.', 'C', 'The author presents the original findings clearly and then introduces the 2019 study as a complication, neither dismissing nor uncritically accepting either.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p2, v_read_unit2, 'The passage primarily presents jazz as:', 'A form invented by a single musician in New Orleans.', 'A European import adapted by African American musicians.', 'The product of multiple converging musical traditions.', 'A reaction against the formality of classical music.', 'C', 'The passage explicitly states jazz was "less an invention than a convergence" of African, European, blues, and ragtime traditions.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p2, v_read_unit2, 'According to the passage, what was the function of Congo Square?', 'A marketplace where musical instruments were sold.', 'A gathering place where enslaved people preserved African musical traditions.', 'A performance venue where early jazz bands played publicly.', 'A training ground for European classical musicians.', 'B', 'The passage states Congo Square was where "enslaved people gathered on Sundays to maintain African musical traditions through drumming and dance."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p2, v_read_unit2, 'As described in the passage, improvisation in jazz is:', 'The complete absence of musical structure.', 'A reaction against European harmonic traditions.', 'An ongoing negotiation between structure and spontaneity.', 'A technique borrowed directly from ragtime.', 'C', 'The passage defines jazz improvisation as "not the abandonment of structure but an ongoing negotiation between structure and spontaneity."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p2, v_read_unit2, 'What does the passage note about recordings of Buddy Bolden?', 'Several recordings survive in the Library of Congress.', 'His recordings were destroyed in a fire.', 'No recordings of him survive.', 'He refused to be recorded during his career.', 'C', 'The passage explicitly states "no recordings survive" of Buddy Bolden.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 4),
    (v_read_id, v_read_p2, v_read_unit2, 'The passage characterizes New Orleans as "uniquely equipped" for the synthesis of jazz because of:', 'Its proximity to the Mississippi Delta.', 'Its blended creole culture with African, Caribbean, and European influences.', 'Its large population of classically trained musicians.', 'Its history as the most prosperous city in the South.', 'B', 'The passage attributes New Orleans'' unique position to its "creole culture that blended African, Caribbean, and European influences with unusual openness."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p2, v_read_unit2, 'The phrase "less an invention than a convergence" suggests:', 'Jazz was created accidentally rather than intentionally.', 'Jazz did not emerge from a single source but from the meeting of multiple traditions.', 'Jazz was inferior to the musical traditions that preceded it.', 'The origins of jazz are too obscure to identify.', 'B', 'Calling jazz "a convergence" rather than "an invention" emphasizes that it arose from the coming-together of multiple existing traditions rather than from a single creator.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 6),
    (v_read_id, v_read_p2, v_read_unit2, 'The author''s purpose in describing the Bolden legend about being heard "from miles away" is to:', 'Provide a scientifically verified fact about his playing technique.', 'Contrast his style with Louis Armstrong''s.', 'Convey the mythic status Bolden held among musicians of the era.', 'Explain how jazz spread across New Orleans.', 'C', 'A legend about being heard from miles away is not presented as fact but as a measure of the mythic reputation Bolden held in the musical community.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p2, v_read_unit2, 'According to the passage, the Great Migration contributed to jazz history by:', 'Bringing European classical musicians to New Orleans.', 'Spreading jazz northward to cities like Chicago, Detroit, and Harlem.', 'Replacing traditional African musical forms with jazz.', 'Causing the decline of jazz in New Orleans.', 'B', 'The passage states jazz "traveled north with the Great Migration, which carried hundreds of thousands of African Americans — and their music — to Chicago, Detroit, and Harlem."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 8),
    (v_read_id, v_read_p2, v_read_unit2, 'As used in the passage, "synthesis" most nearly means:', 'conflict', 'simplification', 'combination of different elements into a unified whole', 'imitation', 'C', 'The passage uses "synthesis" to describe New Orleans as the place where multiple musical and cultural traditions combined into something new.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p2, v_read_unit2, 'The author''s tone toward jazz and its origins is best described as:', 'critical, questioning the originality of the music.', 'nostalgic, lamenting the loss of early jazz traditions.', 'admiring and informative, tracing origins with evident respect.', 'neutral and clinical, presenting only historical facts.', 'C', 'The language throughout — "extraordinary," "vibrant cultural explosion," "unique" — conveys evident admiration while remaining informative.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p2, v_read_unit2, 'The passage primarily discusses:', 'The life cycle of the monarch butterfly in summer.', 'The mechanics and threats facing the monarch butterfly migration.', 'The oyamel fir forests of Michoacán, Mexico.', 'Climate change effects on butterfly populations globally.', 'B', 'The passage covers how the migration works (navigational tools, multi-generational span) and the primary threats to it (milkweed loss, habitat destruction).', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p2, v_read_unit2, 'The Methuselah generation is described as unusual because:', 'It migrates south in spring rather than autumn.', 'It is smaller than other monarch generations.', 'It lives far longer than summer generations and navigates to a place it has never seen.', 'It can complete the full round trip in a single season.', 'C', 'The passage notes the Methuselah generation lives 6–8 months (vs. 2–6 weeks for summer generations) and navigates to an overwintering site it has never visited.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p2, v_read_unit2, 'According to the passage, monarchs rely on their magnetic sense especially when:', 'Flying over water.', 'The sun is obscured by overcast skies.', 'Temperatures drop below freezing.', 'They cross international borders.', 'B', 'The passage states monarchs rely on magnetic field detection "particularly when skies are overcast" — when the sun compass is unavailable.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p2, v_read_unit2, 'What did the University of Massachusetts study find?', 'Monarchs use a sun compass more than a magnetic sense.', 'Milkweed decline has no effect on migratory patterns.', 'Disrupting monarchs'' magnetic sense significantly impaired their migratory heading.', 'The Methuselah generation cannot navigate without visual landmarks.', 'C', 'The passage states directly: "disrupting monarchs'' magnetic sense significantly impaired their migratory heading."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 4),
    (v_read_id, v_read_p2, v_read_unit2, 'As used in the first paragraph, "converge" most nearly means:', 'scatter in multiple directions.', 'come together from many directions toward one point.', 'pass through without stopping.', 'search carefully.', 'B', 'Monarchs from across eastern North America "converge on a single mountain range" — they move from many starting points to one destination.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 5),
    (v_read_id, v_read_p2, v_read_unit2, 'What is identified as the greatest threat to the monarch migration?', 'Predation by birds along the migratory route.', 'Disruption of the sun compass by artificial light.', 'Habitat loss, especially the decline of milkweed.', 'Cold temperatures in Michoacán during winter.', 'C', 'The passage explicitly states: "The greatest threat to the monarch migration is habitat loss" and specifies milkweed decline as the primary factor.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 6),
    (v_read_id, v_read_p2, v_read_unit2, 'How many generations does the full round trip of the migration span?', 'One to two', 'Two to three', 'Three to four', 'Four to five', 'C', 'The passage states: "The round trip spans three to four generations."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 7),
    (v_read_id, v_read_p2, v_read_unit2, 'Milkweed has declined primarily because of:', 'Climate change reducing soil moisture.', 'Herbicide use in the American Midwest.', 'Competition from invasive plant species.', 'Overgrazing by livestock.', 'B', 'The passage states milkweed "has declined sharply across the American Midwest due to herbicide use."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 8),
    (v_read_id, v_read_p2, v_read_unit2, 'The detail that monarchs navigate to "the same trees their great-grandparents left" is used to:', 'Explain how trees in Michoacán are specially adapted to monarchs.', 'Emphasize the extraordinary precision of multi-generational navigation.', 'Suggest that monarchs have longer memories than scientists believed.', 'Contrast the Methuselah generation with summer generations.', 'B', 'This detail underscores the remarkable fact that butterflies who have never made the trip navigate to a specific location their ancestors used.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p2, v_read_unit2, 'The overall stance of the passage toward the monarch migration is:', 'Admiring of its complexity while concerned about its survival.', 'Optimistic that conservation efforts will restore the population.', 'Skeptical that the migration is as remarkable as claimed.', 'Neutral, presenting only established scientific facts without emphasis.', 'A', 'The passage uses language like "most remarkable migrations" and "extraordinary" while ending with a stark 80% population decline — admiration combined with conservation concern.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p3, v_read_unit1, 'The narrator''s primary purpose in this passage is to:', 'Argue that immigration policy in the 1920s was unjust.', 'Reflect on what her father chose to share and what he withheld about his immigration experience.', 'Describe the historical conditions at Ellis Island.', 'Celebrate her father''s courage in crossing the Atlantic.', 'B', 'The passage contrasts the story the father told (the harbor, the statue) with what he never spoke of (Ellis Island fear), and the narrator reflects on understanding this contrast now.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 1),
    (v_read_id, v_read_p3, v_read_unit1, 'The cousin''s address was sewn into the jacket lining most likely to:', 'Hide it from immigration inspectors at Ellis Island.', 'Keep it from getting wet during the ocean crossing.', 'Ensure it would not be lost, as a precaution.', 'Follow a tradition common among immigrants of the time.', 'C', 'Sewing the address into the lining is a practical precaution — the most important piece of information is secured somewhere it cannot fall out or be misplaced.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p3, v_read_unit1, 'The father''s story about the Statue of Liberty is presented as something he:', 'Told only once, reluctantly and with difficulty.', 'Told repeatedly in the same way, with a practiced pause for the laugh.', 'Regretted sharing because it made him seem naive.', 'Embellished significantly over the years.', 'B', 'The passage says he "would tell the story often," "always began the same way," and "pause there, waiting for the laugh" — a polished, repeated performance.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 3),
    (v_read_id, v_read_p3, v_read_unit1, '"He gave us the story he wanted us to have" suggests:', 'He was an unreliable narrator who invented the experience.', 'He deliberately shaped what his children knew of his immigration experience.', 'He was embarrassed by what happened at Ellis Island.', 'He could not remember the details of his arrival accurately.', 'B', 'This line implies intentionality — the father chose which stories to tell and which to withhold, constructing a particular version of himself for his children.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p3, v_read_unit1, 'What the father "rarely spoke of" about Ellis Island primarily conveys:', 'The efficient processing system immigrants experienced.', 'The bureaucratic confusion caused by language barriers.', 'The vulnerability and fear underlying the immigration experience.', 'His resentment toward American immigration authorities.', 'C', 'The details he withheld — name mispronounced, medical inspection, uncertainty about being admitted — all center on fear and vulnerability.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p3, v_read_unit1, 'The cardboard suitcase and its contents most likely serve to convey:', 'The poverty and sparse preparation with which he made the journey.', 'The mother''s love expressed through practical gifts.', 'The ease of immigration in the 1920s.', 'The father''s confidence in his new country.', 'A', 'A cardboard suitcase with a change of clothes, cheese, and a letter of introduction conveys the bare, minimal resources with which he emigrated.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 6),
    (v_read_id, v_read_p3, v_read_unit1, 'As used in the final paragraph, "carried differently" most likely means:', 'He stored those memories in a different location.', 'He bore the difficult memories privately, not as shared stories.', 'He forgot the painful parts of the experience over time.', 'He discussed the Ellis Island experience only with other immigrants.', 'B', 'The contrast with "gave us the story he wanted us to have" implies the rest was not given — it was carried privately, as unshared inner experience.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 7),
    (v_read_id, v_read_p3, v_read_unit1, 'The narrator''s understanding at sixty-three that she "could not at twelve" suggests:', 'She has recently done historical research on Ellis Island.', 'She learned the truth from other family members when she was older.', 'Maturity gave her new insight into why her father withheld part of his story.', 'She now believes her father''s account was inaccurate.', 'C', 'The contrast between ages twelve and sixty-three is about perspective — adult experience allows her to understand the emotional logic of her father''s selective storytelling.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p3, v_read_unit1, 'The inspector mispronouncing and rewriting the father''s name most likely suggests:', 'The father chose to change his name upon arriving in America.', 'The loss or alteration of identity that immigrants experienced at entry.', 'Ellis Island inspectors spoke many languages.', 'The father''s name was too difficult to spell correctly.', 'B', 'Name alteration at Ellis Island is a historically documented symbol of the identity transformation — often involuntary — that immigrants experienced on entry.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p3, v_read_unit1, 'The tone of the final paragraph is best described as:', 'Quietly reflective and compassionate toward her father.', 'Bitter about what she was not told as a child.', 'Admiring and celebratory of her father''s achievement.', 'Detached and analytical.', 'A', 'The narrator does not blame her father or express regret — "I understand this now" conveys a mature, compassionate comprehension of his choices.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p3, v_read_unit2, 'The passage primarily argues that:', 'The FHA successfully expanded homeownership for all Americans.', 'Federal housing policy created and perpetuated racial economic inequality.', 'Redlining was eliminated by federal policy in the 1960s.', 'Suburban expansion was the primary cause of urban poverty.', 'B', 'The passage traces how FHA risk assessments denied Black families access to wealth-building loans, with effects measurable today.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p3, v_read_unit2, 'According to the passage, what determined which neighborhoods received the highest FHA ratings?', 'The age and condition of housing stock.', 'The income levels of individual applicants.', 'The neighborhood being predominantly white and middle-class.', 'Proximity to employment centers.', 'C', 'The passage states "Neighborhoods deemed low risk — typically white, middle-class suburbs — received the highest ratings."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p3, v_read_unit2, '"Redlining" as described in the passage refers to:', 'A practice of marking boundaries of approved development zones.', 'The practice of outlining minority neighborhoods in red on risk assessment maps.', 'A legal method for identifying defaulted mortgages.', 'The color-coding used by FHA inspectors for substandard housing.', 'B', 'The passage explicitly states: neighborhoods with significant minority populations "were outlined in red on the maps — a practice that gave rise to the term ''redlining.''"', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 3),
    (v_read_id, v_read_p3, v_read_unit2, 'The phrase "regardless of their individual creditworthiness" suggests:', 'All residents of redlined areas had poor credit histories.', 'Banks required credit scores that were impossible for most Americans to achieve.', 'Residents were denied loans based on neighborhood demographics, not personal qualifications.', 'Individual creditworthiness was never a factor in FHA lending decisions.', 'C', 'This phrase emphasizes that the denial was systemic and race-based, not a reflection of any individual''s financial standing.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p3, v_read_unit2, 'According to the passage, why were many African American families unable to build wealth through housing?', 'They preferred renting to owning property.', 'FHA mortgages required larger down payments than white families faced.', 'They were locked out of the FHA mortgage market and forced into predatory contracts.', 'Their neighborhoods had lower property taxes that reduced equity growth.', 'C', 'The passage states African American families "were locked out of that market" and "forced into predatory rent-to-own contracts," preventing equity accumulation.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p3, v_read_unit2, 'The 2020 study about temperatures primarily serves to:', 'Explain why redlined neighborhoods were originally considered high risk.', 'Show that redlining''s effects persist in physical as well as economic form.', 'Demonstrate that climate change disproportionately affects urban areas.', 'Argue that tree cover reduces property values.', 'B', 'The 14-degree temperature difference due to underinvestment in green space shows redlining''s legacy extends beyond economics into the physical environment of affected neighborhoods.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 6),
    (v_read_id, v_read_p3, v_read_unit2, 'According to the passage, banks and insurance companies used the FHA maps to:', 'Identify neighborhoods suitable for commercial development.', 'Assess the risk of natural disasters in urban areas.', 'Deny credit and insurance to residents of redlined neighborhoods.', 'Calculate property tax rates for municipal governments.', 'C', 'The passage states banks and insurance companies "adopted the same maps, effectively denying credit and insurance to residents of redlined areas."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 7),
    (v_read_id, v_read_p3, v_read_unit2, 'As used in paragraph three, "accumulate" most nearly means:', 'inherit', 'spend', 'build up over time', 'transfer between generations', 'C', '"Accumulate the same intergenerational wealth" means build up wealth over time — here, through rising home equity — in the way white families could via FHA loans.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p3, v_read_unit2, 'Which finding would most directly support the passage''s central claim about lasting inequality?', 'A study showing that suburbs built in the 1940s have higher property values today.', 'Research confirming that FHA loan terms were identical for all applicants.', 'Studies showing that today''s redlined neighborhoods have lower median incomes and homeownership rates than non-redlined areas.', 'Evidence that rent-to-own contracts are now regulated by federal law.', 'C', 'The central claim is that redlining created lasting inequality. A direct correlation between 1930s redlined boundaries and current economic disadvantage is the strongest support.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p3, v_read_unit2, 'The author''s tone in describing the FHA program is best described as:', 'Nostalgic, celebrating the expansion of homeownership it enabled.', 'Critical, highlighting the discriminatory outcomes of a nominally beneficial program.', 'Defensive, arguing that the FHA acted in good faith given the era.', 'Neutral, presenting the program''s history without judgment.', 'B', 'The author notes the FHA''s "stated goal" of accessibility but focuses on how it systematically excluded Black families — a critical framing.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p3, v_read_unit2, 'The passage is primarily about:', 'Gutenberg''s personal life and motivations.', 'The transformative social and political effects of the printing press.', 'The technical specifications of Gutenberg''s printing press.', 'The decline of manuscript culture in medieval Europe.', 'B', 'The passage focuses on what the printing press changed — book production costs, language standardization, new reading publics, and the Reformation.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p3, v_read_unit2, 'According to the passage, by approximately how much did the printing press reduce book production costs?', '50 percent', '75 percent', '95 percent', '99 percent', 'C', 'The passage states the press "reduced the cost of producing a book by roughly 95 percent."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p3, v_read_unit2, 'The comparison to "all the scribes in Europe in the previous thousand years" is used to:', 'Criticize the slow pace of manuscript production.', 'Emphasize the unprecedented scale of book production after Gutenberg.', 'Show that scribes quickly adopted the new technology.', 'Explain why European literacy rates were low before 1440.', 'B', 'The fifty-year post-Gutenberg total surpassing a thousand years of scribal work is intended to dramatize the scale of the change in production.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p3, v_read_unit2, 'Print is said to have "standardized languages," which most likely means:', 'Governments imposed official grammars on their citizens.', 'Regional dialects were immediately eliminated by printing.', 'It created shared written forms that reduced regional variation and supported national identity.', 'Printed texts could only be read by those who spoke standard dialects.', 'C', 'The passage describes standardization as creating "shared written forms" that "helped erode regional dialects and strengthen nascent national identities."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p3, v_read_unit2, 'The passage identifies what as the most dramatic consequence of the printing press?', 'The standardization of European languages.', 'The creation of new reading publics beyond the clergy.', 'The Protestant Reformation.', 'The decline of monastic scriptoria.', 'C', 'The passage explicitly says: "Perhaps the most dramatic consequence was the Protestant Reformation."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 5),
    (v_read_id, v_read_p3, v_read_unit2, 'According to the passage, why was Luther''s Ninety-Five Theses able to spread so quickly?', 'Luther had a large network of supporters who copied the text by hand.', 'Printers reproduced it in thousands of copies within weeks.', 'The Church initially endorsed its wide distribution.', 'It was translated into Latin and distributed internationally.', 'B', 'The passage states: "printers not reproduced them in their thousands within weeks" — the press enabled mass distribution of a document that might otherwise have remained local.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 6),
    (v_read_id, v_read_p3, v_read_unit2, 'As used in the passage, "nascent" most nearly means:', 'ancient', 'declining', 'newly forming or emerging', 'well-established', 'C', '"Nascent national identities" are those just coming into being — print helped form them by creating shared written languages.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p3, v_read_unit2, 'The new reading publics created by print were significant because they:', 'Were more educated than previous reading publics.', 'Could access texts independently of the Church''s interpretive authority.', 'Had more leisure time than the clergy and nobility.', 'Preferred secular texts to religious ones.', 'B', 'The passage emphasizes that merchants, artisans, and ordinary citizens could "access texts independently of the Church''s interpretive authority" — a shift in who controlled knowledge.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p3, v_read_unit2, 'The historians'' disagreement mentioned in the final paragraph concerns:', 'Whether Gutenberg actually invented the printing press.', 'How much direct credit the press deserves for the Reformation and intellectual movements.', 'Whether the Reformation was a positive or negative development.', 'The accuracy of the twenty-million-book production estimate.', 'B', 'The passage states: "Historians disagree about how much credit to give the printing press for the Reformation and the broader intellectual movements that followed."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 9),
    (v_read_id, v_read_p3, v_read_unit2, 'The passage''s central claim about Gutenberg''s press is that it:', 'Primarily improved the speed of communication between governments.', 'Was less influential than historians have traditionally claimed.', 'Changed not just communication speed but who had access to ideas and could shape them.', 'Created economic inequality between literate and illiterate populations.', 'C', 'The final sentence states the press "changed who had access to ideas, and therefore who could participate in shaping them" — the central claim is about democratized access to knowledge.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p3, v_read_unit2, 'The central point of the passage is:', 'Photosynthesis is still the foundation of most life on Earth.', 'The discovery of hydrothermal vent ecosystems overturned fundamental assumptions about life''s requirements.', 'Deep-sea exploration is too expensive and dangerous to continue.', 'The submersible Alvin was an important technological achievement.', 'B', 'The passage traces how the 1977 discovery eliminated sunlight from the assumed prerequisites for life, and extends this to implications for life elsewhere.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p3, v_read_unit2, 'What assumption did the 1977 discovery primarily disprove?', 'That all life requires liquid water.', 'That sunlight is the foundation of all life on Earth.', 'That deep-sea organisms cannot survive without oxygen.', 'That hydrothermal vents only occur in the Pacific Ocean.', 'B', 'The passage opens with the assumption that "sunlight was the foundation of all life on Earth" and then states this assumption "was overturned in 1977."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p3, v_read_unit2, 'As described in the passage, "chemosynthesis" means:', 'The conversion of light energy into sugars by plants.', 'The process by which deep-sea organisms absorb nutrients from water.', 'The process by which bacteria convert chemical energy from hydrogen sulfide into organic matter.', 'A form of photosynthesis that functions without sunlight.', 'C', 'The passage defines chemosynthesis as "the process by which certain bacteria convert chemical energy from hydrogen sulfide into organic matter."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p3, v_read_unit2, 'Every organism at the hydrothermal vents is ultimately supported by:', 'Nutrients carried down from the ocean surface.', 'The heat energy released by the vents themselves.', 'Chemosynthetic bacteria that form the base of the food chain.', 'Decaying organic matter that sinks from shallower waters.', 'C', 'The passage states: "Every other organism in the community depended on these bacteria" — the chemosynthetic bacteria.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 4),
    (v_read_id, v_read_p3, v_read_unit2, 'What three conditions had scientists previously believed were required for life?', 'Carbon, oxygen, and moderate pressure.', 'Liquid water, sunlight, and moderate temperature range.', 'Sunlight, oxygen, and liquid water.', 'A stable orbit, liquid water, and an atmosphere.', 'B', 'The passage states: "Scientists had believed that liquid water, sunlight, and a moderate temperature range were the three prerequisites for life as we know it."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 5),
    (v_read_id, v_read_p3, v_read_unit2, 'Which condition did the vent communities eliminate from the list of life''s prerequisites?', 'Liquid water', 'Moderate temperature', 'Sunlight', 'An oxygen atmosphere', 'C', 'The passage explicitly states: "The hydrothermal vent communities eliminated sunlight from that list."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 6),
    (v_read_id, v_read_p3, v_read_unit2, 'The passage mentions Europa and Enceladus in order to:', 'Compare their oceans to hydrothermal vents on Earth.', 'Argue that space exploration is more important than deep-sea exploration.', 'Suggest that vent-like ecosystems might support life on other worlds.', 'Show that Jupiter and Saturn''s moons have been scientifically confirmed to harbor life.', 'C', 'The passage uses the Earth example as a model: if life exists without sunlight here, similar conditions on icy moons might support life too.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p3, v_read_unit2, 'As used in the passage, "geothermal" most nearly refers to:', 'energy generated by tidal forces.', 'heat generated by friction between tectonic plates.', 'heat originating from within the Earth.', 'chemical energy stored in deep-sea sediments.', 'C', '"Geothermal activity" refers to heat from within the Earth — the source of the energy that forces superheated water through the seafloor vents.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p3, v_read_unit2, 'The tube worms "up to two meters long" are mentioned primarily to:', 'Demonstrate that all deep-sea creatures are unusually large.', 'Illustrate the unexpected vitality and scale of life at the vents.', 'Explain how chemosynthesis enables organisms to grow rapidly.', 'Contrast vent organisms with surface-dwelling species.', 'B', 'Two-meter tube worms exemplify that the ecosystem is not merely surviving but thriving — the size emphasizes abundance and vitality.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p3, v_read_unit2, 'The author''s purpose in the final paragraph is to:', 'Caution against excessive optimism about finding extraterrestrial life.', 'Summarize the technical details of the Alvin submersible.', 'Extend the significance of the 1977 discovery to broader questions about life in the solar system.', 'Argue that further deep-sea research should be funded.', 'C', 'The final paragraph explicitly uses the vent ecosystem as "a model for what life might look like elsewhere in the solar system," extending the discovery''s significance beyond Earth.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p4, v_read_unit1, 'The passage is primarily concerned with:', 'Mira''s cataloguing of her father''s map collection after his death.', 'The history of cartography as a scholarly discipline.', 'Mira''s discovery that her father had been mapping an imaginary place.', 'The value of the maps as historical artifacts.', 'C', 'The passage builds to Mira''s discovery of the unfinished, unrecognizable maps and her realization that her father had been mapping something imaginary.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p4, v_read_unit1, 'The detail that the chair "still smelled faintly of pipe tobacco he had given up twenty years ago" primarily serves to:', 'Establish that the study has not been cleaned since her father''s death.', 'Evoke the lingering presence of her father in the space.', 'Show that Mira''s father was careless about his health.', 'Contrast the past with the present state of the house.', 'B', 'The lingering smell — from a habit abandoned two decades ago — conveys the way traces of a person persist long after they are gone, evoking the father''s presence.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p4, v_read_unit1, 'According to the passage, how did her father accumulate so many maps?', 'He purchased them as investments.', 'He collected them over thirty years as a geography professor.', 'He inherited them from his own father.', 'He drew all of them himself during his career.', 'B', 'The passage states: "Her father had been a geography professor for thirty years, and he had accumulated maps the way other people accumulate regrets."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 3),
    (v_read_id, v_read_p4, v_read_unit1, 'The comparison of maps to "regrets" most likely suggests:', 'Her father felt guilty about spending so much on his collection.', 'The maps reminded him of places he had never visited.', 'They accumulated abundantly and somewhat unconsciously over a lifetime.', 'Mira views her father''s obsession as a character flaw.', 'C', 'Regrets are things that accumulate over a life without being sought — the comparison suggests the maps gathered similarly, naturally and abundantly.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 4),
    (v_read_id, v_read_p4, v_read_unit1, 'What makes the unfinished maps different from all the others in the study?', 'They are in worse condition than the other maps.', 'They appear to depict a place Mira cannot identify as real.', 'They were drawn by someone other than her father.', 'They predate all the other maps in the collection.', 'B', 'Unlike the historical and geographic maps she can identify, these maps depict "a coastline unfamiliar, the topography unlike anything on any continent she knew" — an unrecognizable, apparently imaginary place.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p4, v_read_unit1, '"She had never imagined he might also have been mapping somewhere that existed only in his mind" suggests:', 'Mira did not know her father was a geographer.', 'She had assumed his work was always grounded in real, verifiable places.', 'She believes her father was confused before his death.', 'The imaginary maps were a recent change in his scholarly approach.', 'B', 'The phrase "also" suggests she knew about his real-world mapping — the surprise is the discovery of an imaginative, interior dimension she never knew he had.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 6),
    (v_read_id, v_read_p4, v_read_unit1, 'The map dated "three months before he died" most likely emphasizes:', 'The maps were created long before her father became ill.', 'Her father was still actively working on the imaginary maps near the end of his life.', 'The maps are historically valuable because of their age.', 'Her father knew he was dying and left the maps as a message.', 'B', 'The recent date establishes that the imaginary maps were a current, active project — not something from his distant past — which intensifies their significance.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p4, v_read_unit1, 'Each unfinished map being protected by tissue paper most likely suggests:', 'Her father stored all paper documents in tissue to prevent yellowing.', 'He treated these particular maps with special care and intentionality.', 'The maps were fragile due to the unusual materials he used.', 'Mira wrapped them in tissue after finding them.', 'B', 'The careful protection of the unfinished maps — unlike the rolled and stacked others — implies he valued them particularly and took deliberate care of them.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p4, v_read_unit1, 'The phrase "or that she might one day be the one to finish it" most likely implies:', 'Mira has cartographic skills equal to her father''s.', 'Mira is considering completing her father''s imaginary map.', 'The maps are incomplete because her father ran out of materials.', 'Someone has already begun finishing the maps without Mira''s knowledge.', 'B', 'The passage ends on this possibility — Mira holding the map and imagining herself completing it — suggesting she is drawn toward the idea.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p4, v_read_unit1, 'The tone of the passage is best described as:', 'Quietly mysterious and gently sorrowful.', 'Anxious and unsettled.', 'Celebratory of her father''s creative achievement.', 'Detached and academic.', 'A', 'The setting — evenings alone in a dead father''s study, the lingering smells, the unexpected discovery — creates a tone of quiet mystery and subdued grief.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p4, v_read_unit2, 'The Easterlin Paradox refers to:', 'The finding that wealthier individuals are always happier than poorer ones.', 'The observation that countries growing wealthier over time do not become correspondingly happier.', 'The theory that happiness declines after middle age regardless of income.', 'The finding that non-economic factors are unrelated to happiness.', 'B', 'The passage defines it as the observation that national wealth growth does not produce corresponding happiness growth.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p4, v_read_unit2, '"Hedonic adaptation" as described in the passage means:', 'The pursuit of pleasure as the primary goal of human behavior.', 'The tendency to feel increasingly unhappy as income grows.', 'The tendency of people to return to a stable baseline happiness level after life changes.', 'A scientific method for measuring subjective wellbeing.', 'C', 'The passage defines it as "the tendency of people to return fairly quickly to a stable baseline level of happiness after positive or negative life changes."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p4, v_read_unit2, 'What did the 2021 study find?', 'Income has no relationship to happiness at any level.', 'A consistent positive relationship between income and wellbeing at all income levels.', 'Happiness declines above a certain income threshold.', 'Wealthy nations are less happy than developing nations.', 'B', 'The passage states the 2021 study "found a consistent positive relationship between income and subjective wellbeing at all income levels."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 3),
    (v_read_id, v_read_p4, v_read_unit2, 'Which finding would most directly support the Easterlin Paradox?', 'A wealthy country reporting the same average happiness as it did 30 years ago when it was significantly poorer.', 'A study showing that richer individuals within a country report higher happiness than poorer ones.', 'Evidence that marriage increases happiness permanently.', 'Research showing that hedonic adaptation occurs in all cultures.', 'A', 'The Paradox is that national wealth growth does not produce national happiness growth. A wealthy country no happier than it was when poor directly illustrates this.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 4),
    (v_read_id, v_read_p4, v_read_unit2, 'The "other economists" in the final paragraph argue that:', 'The Easterlin Paradox has been definitively proven.', 'Income is the most important factor in wellbeing at all levels.', 'Non-economic factors are the strongest predictors of sustained wellbeing.', 'The 2021 study used flawed methodology.', 'C', 'These economists argue the debate about income misses that "non-economic factors... are the strongest predictors of sustained wellbeing."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p4, v_read_unit2, 'As used in the passage, "threshold" most nearly means:', 'a financial goal', 'a point beyond which something changes', 'a statistical average', 'a minimum requirement', 'B', '"Beyond a certain point, additional income does not improve satisfaction" — "threshold" refers to the level at which further increases stop producing further gains.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 6),
    (v_read_id, v_read_p4, v_read_unit2, 'The 2021 study is presented in the passage as:', 'Definitive proof that the Easterlin Paradox is wrong.', 'A challenge to the Easterlin Paradox based on a much larger dataset.', 'Support for the claim that hedonic adaptation is universal.', 'Evidence that happiness is primarily determined by social factors.', 'B', 'The passage presents the 2021 study as challenging the Paradox, suggesting the earlier finding "may have reflected limitations of the data available in 1974."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p4, v_read_unit2, 'Which of the following is NOT mentioned in the passage as a non-economic predictor of wellbeing?', 'Quality of social relationships', 'Physical health', 'Educational attainment', 'Autonomy at work', 'C', 'The passage mentions social relationships, sense of purpose, physical health, and autonomy at work — but not educational attainment.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p4, v_read_unit2, 'The passage''s final sentence suggests the question of happiness should focus on:', 'How to maximize individual income growth.', 'The conditions under which people live, rather than how much they earn.', 'Measuring national GDP as a proxy for wellbeing.', 'Resolving the debate between the Easterlin Paradox and the 2021 study.', 'B', 'The final economists argue the conversation "should be less about how much people earn and more about the conditions under which they live."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 9),
    (v_read_id, v_read_p4, v_read_unit2, 'The author''s treatment of the happiness-income debate is best described as:', 'Partisan, clearly favoring the Easterlin Paradox over later research.', 'Dismissive, suggesting the debate is unimportant.', 'Balanced, presenting multiple positions without declaring a definitive winner.', 'Optimistic, suggesting the debate will soon be resolved.', 'C', 'The author presents the original Paradox, a challenge to it, and a third perspective that reframes the question — without taking a side.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p4, v_read_unit2, 'The passage is primarily about:', 'The biography of Langston Hughes.', 'The major voices, approaches, and tensions within the Harlem Renaissance.', 'Zora Neale Hurston''s career as an anthropologist.', 'The role of jazz and blues in 1920s New York.', 'B', 'The passage introduces the Renaissance, profiles Hughes and Hurston, and identifies a broader tension their disagreement represents.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p4, v_read_unit2, 'According to the passage, what role did the Great Migration play in the Harlem Renaissance?', 'It brought European artistic influences to Harlem.', 'It concentrated African American artistic talent in Harlem by bringing people from the rural South.', 'It caused political tensions that inspired protest art.', 'It introduced jazz to northern cities for the first time.', 'B', 'The passage states the Great Migration "brought more than a million African Americans from the rural South to northern cities," concentrating talent in Harlem.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 2),
    (v_read_id, v_read_p4, v_read_unit2, 'Langston Hughes''s approach to poetry is best characterized as:', 'Formal and classical, drawing on European poetic traditions.', 'Political and confrontational, directly attacking racial injustice.', 'Drawing on jazz rhythms and asserting the literary power of vernacular language.', 'Personal and introspective, focusing on private experience.', 'C', 'The passage describes Hughes drawing on "cadences of jazz and blues, insisting that African American vernacular language was... a source of power."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p4, v_read_unit2, 'Zora Neale Hurston''s anthropological training influenced her work by:', 'Causing her to write in a strictly academic style.', 'Leading her to collect and use African American folklore, dialect, and oral tradition in her fiction.', 'Making her dismissive of vernacular language as unliterary.', 'Connecting her to the political activism of the movement.', 'B', 'The passage directly links her Columbia anthropology training under Boas to her field collection of "folklore, dialect, and oral tradition" that shaped her novel.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p4, v_read_unit2, 'The criticism of Hurston by some contemporaries suggests:', 'Her writing was considered technically inferior.', 'There was disagreement within the movement about whether art should prioritize personal or political themes.', 'Hughes and Hurston had a long personal rivalry.', 'Anthropological approaches were not respected by literary critics.', 'B', 'The criticism was specifically that she focused on "personal experience rather than political protest" — a disagreement about the purpose and responsibility of Black art.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 5),
    (v_read_id, v_read_p4, v_read_unit2, 'As used in the passage, "vernacular" most nearly means:', 'foreign or borrowed language', 'formal academic language', 'the everyday spoken language of a particular community', 'written language as opposed to spoken', 'C', 'Hughes used the "vernacular language" of everyday African American speech — the informal, community-specific language of lived experience — as a literary medium.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 6),
    (v_read_id, v_read_p4, v_read_unit2, '"I, Too" is described in the passage as:', 'A lament for the exclusion of African Americans from literary culture.', 'An angry protest against racial segregation.', 'A confident declaration of African American voices'' right to occupy the center of American literature.', 'A celebration of the jazz and blues traditions.', 'C', 'The passage describes "I, Too" as declaring "the right of African American voices to occupy the center of American literary culture — with quiet, unshakable confidence."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 7),
    (v_read_id, v_read_p4, v_read_unit2, 'The "broader tension" identified in the final paragraph is between:', 'The northern and southern wings of the Great Migration.', 'Hughes''s poetry and Hurston''s novels as art forms.', 'Art as political weapon and art as cultural expression.', 'Established African American artists and newcomers to Harlem.', 'C', 'The passage explicitly frames the Hughes-Hurston disagreement as an instance of the broader tension "between art as political weapon and art as cultural expression."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p4, v_read_unit2, 'The passage''s final sentence suggests the Harlem Renaissance''s enduring value lies in:', 'Hughes winning the argument about art''s political responsibility.', 'Its production of a unified, coherent artistic vision.', 'Its multiplicity of unresolved voices and purposes.', 'The commercial success of artists like Hughes and Hurston.', 'C', 'The passage states the achievement "may lie precisely in this unresolved multiplicity of voices and purposes" — the diversity itself is the legacy.', 'MULTIPLE_CHOICE', 'HARD', v_group_id, 9),
    (v_read_id, v_read_p4, v_read_unit2, 'The author''s tone in discussing the Hughes-Hurston disagreement is best described as:', 'Critical of Hughes for attacking Hurston''s work.', 'Analytical and even-handed, presenting both positions fairly.', 'Nostalgic for the cultural vitality of the 1920s.', 'Dismissive of the disagreement as unimportant.', 'B', 'The author presents both positions without endorsing either, frames the disagreement as representative of a broader productive tension, and credits both artists.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
    INSERT INTO question_groups (idpaper, title, contexttext, orderindex)
    INSERT INTO quizes (idcourse, idpaper, idunit, questiontext, optiona, optionb, optionc, optiond, correctanswer, explanation, question_type, difficulty, idquestiongroup, grouporderindex)
    VALUES
    (v_read_id, v_read_p4, v_read_unit2, 'The passage is primarily about:', 'Alfred Wegener''s personal struggle to have his theory accepted.', 'How the theory of plate tectonics developed from Wegener''s early hypothesis.', 'The formation of mountains through volcanic activity.', 'The history of oceanographic exploration in the Atlantic.', 'B', 'The passage traces the arc from Wegener''s rejected hypothesis to the discovery of seafloor spreading to the fully developed theory of plate tectonics.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 1),
    (v_read_id, v_read_p4, v_read_unit2, 'According to the passage, what was the main weakness in Wegener''s original theory?', 'His fossil evidence was later proved incorrect.', 'He published before the theory was fully developed.', 'He could not explain the mechanism by which continents move.', 'His coastline comparison was only approximate, not precise.', 'C', 'The passage states: "Wegener could not explain the mechanism by which continents, embedded in solid rock, could move through even harder oceanic rock."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 2),
    (v_read_id, v_read_p4, v_read_unit2, 'What discovery provided the missing mechanism for continental movement?', 'Fossil evidence showing identical species on separate continents.', 'The mid-ocean ridge and the pattern of seafloor spreading.', 'The discovery of subduction zones along coastlines.', 'Seismic data revealing the structure of the Earth''s mantle.', 'B', 'The passage states that the mid-ocean ridge and its rock-age pattern showed "new seafloor was continuously being created at the ridge and spreading outward — carrying the continents with it."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 3),
    (v_read_id, v_read_p4, v_read_unit2, '"Subduction" as described in the passage refers to:', 'The process by which mountains form when two continental plates collide.', 'The spreading of new seafloor from mid-ocean ridges.', 'One tectonic plate being forced beneath another, potentially triggering earthquakes and volcanoes.', 'The gradual sinking of oceanic crust over millions of years.', 'C', 'The passage defines subduction as the process where "one plate is forced beneath the other," which "can trigger earthquakes and volcanoes."', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 4),
    (v_read_id, v_read_p4, v_read_unit2, 'The pattern found in seafloor rocks near the mid-ocean ridge showed that:', 'Rocks were uniformly young near the ridge and the ocean floor.', 'Rocks grew progressively older with distance from the ridge.', 'The oldest rocks were found at the ridge''s center.', 'Rock age was unrelated to distance from the ridge.', 'B', 'The passage states rocks "grew progressively older with distance from the ridge," indicating new rock is created at the ridge and older rock spreads outward.', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 5),
    (v_read_id, v_read_p4, v_read_unit2, 'According to the passage, Wegener''s theory was dismissed for decades because:', 'His fossil evidence was challenged by competing evidence.', 'Geologists at the time did not accept that Africa and South America were once connected.', 'He could not explain how continents could move through solid rock.', 'He published in German and his work was not widely translated.', 'C', 'The passage states the theory was dismissed because Wegener "could not explain the mechanism by which continents, embedded in solid rock, could move through even harder oceanic rock."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 6),
    (v_read_id, v_read_p4, v_read_unit2, 'As used in the passage, "synthesis" most nearly means:', 'conflict or debate', 'simplification of complex data', 'a combining of different theories into a unified framework', 'experimental verification', 'C', 'Plate tectonics is called "the modern synthesis of Wegener''s continental drift and seafloor spreading" — a combination of two theories into one unified framework.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 7),
    (v_read_id, v_read_p4, v_read_unit2, 'The final sentence about the highest mountains once being "the floor of an ancient sea" serves to:', 'Disprove the theory that mountains form through volcanic activity.', 'Illustrate the dramatic scale of geological transformation explained by plate tectonics.', 'Show that Wegener''s original theory predicted the location of mountain ranges.', 'Contrast ocean geography with land geography.', 'B', 'This closing image — sea floor becoming the world''s tallest mountains — is a vivid illustration of the massive, long-term changes that plate tectonics makes comprehensible.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 8),
    (v_read_id, v_read_p4, v_read_unit2, 'The passage suggests the discovery of seafloor spreading was significant primarily because it:', 'Disproved Wegener''s continental drift hypothesis entirely.', 'Confirmed that the Atlantic Ocean was formed by volcanic activity.', 'Provided the missing mechanism that validated continental drift.', 'Led directly to the discovery of subduction zones.', 'C', 'The passage states "The mechanism Wegener lacked had been found" — seafloor spreading supplied the missing explanation that had caused his theory to be rejected.', 'MULTIPLE_CHOICE', 'MEDIUM', v_group_id, 9),
    (v_read_id, v_read_p4, v_read_unit2, 'How does the author characterize modern geology compared to geology before plate tectonics?', 'More speculative and less grounded in direct observation.', 'Narrower in scope, focusing mainly on earthquakes and volcanoes.', 'Transformed into a dynamic, predictive science.', 'Dependent on technology unavailable to earlier geologists.', 'C', 'The passage''s final paragraph states that the recognition of constant plate motion "has transformed geology into a dynamic, predictive science."', 'MULTIPLE_CHOICE', 'EASY', v_group_id, 10);
